{
  "criteria": [
    {
      "id": "C1",
      "level": "Adequate",
      "mark": 6,
      "evidence": [
        {
          "where": "Mission Concept & Rationale",
          "quote": "A near-real-time relay to monitoring stations on the ground would allow marine and conservation scientists to more accurately predict and react to coral bleaching events."
        },
        {
          "where": "Mission Concept & Rationale",
          "quote": "This tool could be applied to a new satellite over the Great Barrier Reef."
        }
      ],
      "reasoning": "The need, intended users, and general monitoring function are clear and supported by sources. However, mission objectives and requirements remain broad: the report does not specify sensor capabilities, coverage, revisit, data products, or measurable performance targets."
    },
    {
      "id": "C2",
      "level": "Adequate",
      "mark": 6,
      "evidence": [
        {
          "where": "Image 1",
          "quote": ""
        },
        {
          "where": "Project Plan & Preliminary Progress",
          "quote": "In addition to my own research, the syllabus work on astrodynamics will help me to understand and design an optimal mission."
        },
        {
          "where": "Project Plan & Preliminary Progress",
          "quote": "Weeks 7 and 8 are reserved for review, amendments, final simulations, and reflection."
        }
      ],
      "reasoning": "The Gantt chart and task descriptions provide a feasible sequence and include launch, orbit, ground control, communications, and STK work. The plan has little contingency provision, planned information sources are not comprehensively identified, and the stated editing weeks conflict with the chart, which places finalisation in weeks 9–10."
    },
    {
      "id": "C3",
      "level": "Deficient",
      "mark": 3,
      "evidence": [
        {
          "where": "Project Plan & Preliminary Progress",
          "quote": "My current choice is a geostationary orbit at an altitude of 600 km, which keeps the satellite fixed above the reef at all times."
        },
        {
          "where": "Project Plan & Preliminary Progress",
          "quote": "also completed STK tutorials 1, 2, 3 & 4."
        }
      ],
      "reasoning": "The report shows background reading and software tutorials, but includes no useful calculations, simulation results, or preliminary design outputs. The one specific orbital proposal is physically inconsistent, so it does not provide reliable technical progress."
    },
    {
      "id": "C4",
      "level": "Adequate",
      "mark": 6,
      "evidence": [
        {
          "where": "Mission Concept & Rationale",
          "quote": "Mission Concept & Rationale"
        },
        {
          "where": "Image 1",
          "quote": ""
        },
        {
          "where": "Mission Concept & Rationale",
          "quote": "¹ https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-acidification"
        }
      ],
      "reasoning": "The report is logically sectioned and readable, and the Gantt chart is legible and labelled. The prose is occasionally informal, the references are presented as URLs rather than a consistently formatted reference list, and the schedule inconsistency reduces clarity. Overall, presentation is adequate but not fully professional."
    }
